talia: quick note- i opened a tiny PR to tighten the streaming + pagination examples across python/typescript/go and add a small 'checkpoint token' helper so iterators don't rewind to page 1 on transient failures. PR: https://github.com/redwood-inference/docs/pull/560

omar: can you paste the minimal py/ts/go examples here so i can eyeball error handling?

talia: python (sync):

# python sync example
from redwood import Client
from redwood.docs_utils import resume_with_checkpoint
client = Client()
checkpoint = None
for page in resume_with_checkpoint(lambda token: client.stream_pages(page_token=token), checkpoint):
  handle(page)
  checkpoint = page.next_token


talia: typescript (async):

// ts async example
import { Redwood } from '@redwood/inference'
import { resumeWithCheckpoint } from '@redwood/docs-utils'
const client = new Redwood()
let checkpoint = null
for await (const page of resumeWithCheckpoint(() => client.streamPages({ pageToken: checkpoint }))) {
  handlePage(page)
  checkpoint = page.nextToken ?? null
}


talia: go (concise):

// go example (single-writer checkpoint)
ctx := context.Background()
client := redwood.NewClient()
checkpoint := ""
for {
  iter, err := client.StreamPages(ctx, &redwood.StreamOptions{PageToken: checkpoint})
  if err != nil {
    if !isTransient(err) { log.Fatalf("stream failed: %v", err) }
    time.Sleep(backoffWithJitter())
    continue
  }
  for iter.Next() {
    p := iter.Page()
    processPage(p)
    if p.NextToken != "" { checkpoint = p.NextToken }
  }
  if checkpoint == "" { break }
}


